create temporary table iflow_test_temp_initializer (id integer);
create function pg_temp.assert(condition boolean,label text) returns void
language plpgsql as $$ begin
 if condition is distinct from true then raise exception 'FAIL: %',label; end if;
 raise notice 'PASS: %',label;
end $$;
update public.iflow_settings set owner_email='agency-owner@example.test',delivery_enabled=true,reminder_after_minutes=1440 where id=1;
select pg_temp.assert((public.iflow_submit('{"name":" Jordan Lee ","email":" OWNER@EXAMPLE.TEST ","service":"Website","message":"Please build a new website."}'::jsonb)->>'ok')::boolean,'valid inquiry is stored');
select pg_temp.assert((public.iflow_submit('{"name":"Other","email":"owner@example.test","service":"Website","message":" Please   build a new website. "}'::jsonb)->>'duplicate')::boolean,'equivalent open inquiry is reused');
select pg_temp.assert((public.iflow_submit('{"name":"A","email":"bad","service":"Other","message":"Hi"}'::jsonb)->>'ok')::boolean is false,'invalid inquiry is rejected');
select pg_temp.assert((select count(*)=1 from public.iflow_inquiries where email='owner@example.test'),'one matching inquiry is stored');
select pg_temp.assert((select count(*)=1 from public.iflow_history where to_status='new'),'new inquiry gets one history record');
select pg_temp.assert((select count(*)=1 from public.iflow_notifications where kind='new_inquiry'),'inquiry and email job are committed together');
do $$ declare v_claim jsonb; v_id uuid; v_token uuid; v_result jsonb;
begin
 v_claim:=public.iflow_claim();
 v_id:=(v_claim->'jobs'->0->>'id')::uuid;v_token:=(v_claim->'jobs'->0->>'lease_token')::uuid;
 perform pg_temp.assert(v_id is not null,'worker atomically claims queued email');
 v_result:=public.iflow_authorize_send(v_id,v_token);
 perform pg_temp.assert((v_result->>'allowed')::boolean,'claimed email is authorized for the configured owner');
 update public.iflow_notifications set lease_until=now()-interval '1 second' where id=v_id;
 v_claim:=public.iflow_claim();
 v_token:=(v_claim->'jobs'->0->>'lease_token')::uuid;
 perform pg_temp.assert((v_claim->'jobs'->0->>'id')::uuid=v_id,'expired lease is recovered after worker restart');
 v_result:=public.iflow_authorize_send(v_id,v_token);
 perform pg_temp.assert((v_result->>'allowed')::boolean,'recovered email gets a fresh authorization');
 perform public.iflow_finish(v_id,v_token,false,null,true,'Temporary test failure',0);
 perform pg_temp.assert((select state='pending' and attempts=2 from public.iflow_notifications where id=v_id),'temporary email failure is retried with bounded attempt tracking');
 update public.iflow_notifications set next_attempt_at=now() where id=v_id;
 v_claim:=public.iflow_claim();v_token:=(v_claim->'jobs'->0->>'lease_token')::uuid;
 perform public.iflow_authorize_send(v_id,v_token);
 perform public.iflow_finish(v_id,v_token,true,'email_test_delivery',false,null,0);
 perform pg_temp.assert((select state='sent' and attempts=3 and provider_id='email_test_delivery' from public.iflow_notifications where id=v_id),'successful retry records provider delivery');
end $$;
update public.iflow_settings set reminder_after_minutes=1 where id=1;
update public.iflow_inquiries set created_at=now()-interval '2 minutes' where email='owner@example.test';
select pg_temp.assert((public.iflow_schedule_reminders()->>'queued')::integer=1,'overdue new inquiry queues one reminder');
select pg_temp.assert((public.iflow_schedule_reminders()->>'queued')::integer=0,'second scheduler run does not duplicate reminder');
select pg_temp.assert((public.iflow_update_status((select id from public.iflow_inquiries where email='owner@example.test'),'contacted')->>'ok')::boolean,'staff can mark contacted');
select pg_temp.assert((select state='cancelled' from public.iflow_notifications where kind='reminder'),'contacting cancels queued reminder');
select pg_temp.assert((public.iflow_schedule_reminders()->>'queued')::integer=0,'contacted inquiry is not reminded');
select pg_temp.assert((public.iflow_update_status((select id from public.iflow_inquiries where email='owner@example.test'),'closed')->>'ok')::boolean,'staff can close an inquiry');
select pg_temp.assert((public.iflow_update_status((select id from public.iflow_inquiries where email='owner@example.test'),'contacted')->>'ok')::boolean is false,'closed inquiry cannot be reopened');
update public.iflow_settings set next_report_week=(date_trunc('week',now() at time zone 'Asia/Singapore')::date-14) where id=1;
select pg_temp.assert((public.iflow_submit('{"name":"Report New","email":"report-new@example.test","service":"Website","message":"Unanswered report sample."}'::jsonb)->>'ok')::boolean,'unanswered report sample is stored');
select pg_temp.assert((public.iflow_submit('{"name":"Report Contacted","email":"report-contacted@example.test","service":"Maintenance","message":"Contacted report sample."}'::jsonb)->>'ok')::boolean,'contacted report sample is stored');
select pg_temp.assert((public.iflow_submit('{"name":"Report Closed","email":"report-closed@example.test","service":"E-commerce","message":"Closed report sample."}'::jsonb)->>'ok')::boolean,'closed report sample is stored');
update public.iflow_inquiries i set created_at=(s.next_report_week::timestamp at time zone 'Asia/Singapore')+interval '1 day' from public.iflow_settings s where i.email='report-new@example.test';
update public.iflow_inquiries i set created_at=(s.next_report_week::timestamp at time zone 'Asia/Singapore')+interval '2 days' from public.iflow_settings s where i.email='report-contacted@example.test';
update public.iflow_inquiries i set created_at=(s.next_report_week::timestamp at time zone 'Asia/Singapore')+interval '3 days' from public.iflow_settings s where i.email='report-closed@example.test';
select pg_temp.assert((public.iflow_update_status((select id from public.iflow_inquiries where email='report-contacted@example.test'),'contacted')->>'ok')::boolean,'weekly sample can be marked contacted');
select pg_temp.assert((public.iflow_update_status((select id from public.iflow_inquiries where email='report-closed@example.test'),'closed')->>'ok')::boolean,'weekly sample can be closed');
update public.iflow_history h set changed_at=(s.next_report_week::timestamp at time zone 'Asia/Singapore')+interval '2 days' from public.iflow_inquiries i,public.iflow_settings s where h.inquiry_id=i.id and i.email='report-contacted@example.test' and h.to_status='contacted';
update public.iflow_history h set changed_at=(s.next_report_week::timestamp at time zone 'Asia/Singapore')+interval '3 days' from public.iflow_inquiries i,public.iflow_settings s where h.inquiry_id=i.id and i.email='report-closed@example.test' and h.to_status='closed';
select pg_temp.assert((public.iflow_schedule_reports()->>'weeks_processed')::integer>=1,'completed report period is processed');
select pg_temp.assert((select count(*)=1 from public.iflow_notifications where event_key='weekly/'||(date_trunc('week',now() at time zone 'Asia/Singapore')::date-14)::text),'weekly report period is queued once');
select pg_temp.assert((select payload->>'text' like '%New inquiries: 3%' and payload->>'text' like '%Marked contacted: 1%' and payload->>'text' like '%Closed: 1%' and payload->>'text' like '%Still unanswered now: 1%' from public.iflow_notifications where event_key='weekly/'||(date_trunc('week',now() at time zone 'Asia/Singapore')::date-14)::text),'weekly report totals match seeded data');
select pg_temp.assert((public.iflow_schedule_reports()->>'weeks_processed')::integer>=0,'repeated report scheduler run succeeds');
select pg_temp.assert((select count(*)=1 from public.iflow_notifications where event_key='weekly/'||(date_trunc('week',now() at time zone 'Asia/Singapore')::date-14)::text),'repeated report scheduler run does not duplicate the same period');
select pg_temp.assert((select count(*)=count(distinct event_key) from public.iflow_notifications),'notification event keys are unique');
set role anon;
do $$ begin
 begin perform public.iflow_submit('{"name":"Anonymous","email":"anon@example.test","service":"Website","message":"No access please."}'::jsonb);raise exception 'anonymous RPC unexpectedly succeeded';
 exception when insufficient_privilege then raise notice 'PASS: anon cannot invoke privileged RPC';end;
 begin perform count(*) from public.iflow_inquiries;raise exception 'anon table query unexpectedly succeeded';
 exception when insufficient_privilege then raise notice 'PASS: anon cannot read inquiry table';end;
end $$;
reset role;
set role authenticated;
do $$ begin
 begin perform public.iflow_submit('{"name":"Browser","email":"browser@example.test","service":"Website","message":"No access please."}'::jsonb);raise exception 'browser RPC unexpectedly succeeded';
 exception when insufficient_privilege then raise notice 'PASS: browser role cannot invoke privileged RPC';end;
 begin perform count(*) from public.iflow_notifications;raise exception 'browser queue query unexpectedly succeeded';
 exception when insufficient_privilege then raise notice 'PASS: browser role cannot read notification queue';end;
end $$;
reset role;
